"use client"

import { CartesianGrid, Scatter, ScatterChart, XAxis, YAxis, ZAxis } from "recharts"

import {
  ChartContainer,
  ChartLegend,
  ChartLegendContent,
  ChartTooltip,
  ChartTooltipContent,
  type ChartConfig,
} from "@/components/ui/chart"

/** Scatter chart on the shadcn chart primitives; one Scatter per series, colored --chart-1..5. */
function ChartScatter({
  series,
  xLabel = "x",
  yLabel = "y",
  axes = true,
  legend = true,
  tooltip = true,
  className,
}: {
  series: { key: string; label: string; points: { x: number; y: number; z?: number }[] }[]
  xLabel?: string
  yLabel?: string
  axes?: boolean
  legend?: boolean
  tooltip?: boolean
  className?: string
}) {
  const config = Object.fromEntries(
    series.map((s, i) => [s.key, { label: s.label, color: `var(--chart-${(i % 5) + 1})` }])
  ) satisfies ChartConfig
  return (
    <ChartContainer config={config} className={className}>
      <ScatterChart accessibilityLayer margin={{ left: 12, right: 12, top: 8 }}>
        {axes && <CartesianGrid />}
        <XAxis type="number" dataKey="x" name={xLabel} hide={!axes} tickLine={false} axisLine={false} tickMargin={8} />
        <YAxis type="number" dataKey="y" name={yLabel} hide={!axes} tickLine={false} axisLine={false} tickMargin={8} width={40} />
        <ZAxis type="number" dataKey="z" range={[40, 200]} />
        {tooltip && <ChartTooltip cursor={false} content={<ChartTooltipContent />} />}
        {series.map((s) => (
          <Scatter key={s.key} name={s.key} data={s.points} fill={`var(--color-${s.key})`} />
        ))}
        {legend && <ChartLegend content={<ChartLegendContent />} />}
      </ScatterChart>
    </ChartContainer>
  )
}

export { ChartScatter }
